def svcpage(num,title,sub,col,items,note):
    cells="".join('<div class="card" style="padding:3.5mm"><div style="display:flex;gap:2.5mm"><span class="num" style="font-size:12pt;color:%s">%s</span><div><h3 style="font-size:10pt">%s</h3><p class="tiny" style="margin-top:.8mm">%s</p></div></div></div>'%(col,n,t,d) for n,t,d in items)
    return '<div class="pad"><div class="eyebrow" style="color:%s">%s</div><h2 style="margin:2mm 0">%s</h2><p class="lead" style="font-size:10.5pt">%s</p><div class="grid g2" style="margin-top:5mm;gap:3.5mm">%s</div>%s</div>'%(col,num,title,sub,cells,note)
A.page(svcpage("03 · Marketing số","Marketing số","Từ nghiên cứu và chiến lược đến phân phối, chuyển đổi, dữ liệu và thương mại điện tử — mỗi hoạt động kết nối với hành trình khách hàng và mục tiêu đo lường được.","#2563FF",[("01","Chiến lược Marketing","Nghiên cứu thị trường, khách hàng, đối thủ; chiến lược, kế hoạch, ngân sách, phễu và KPI."),("02","Xây dựng thương hiệu","Định vị, kiến trúc thương hiệu, naming, slogan, logo, nhận diện, guideline, bao bì, POSM."),("03","Sáng tạo & nội dung","Chiến lược nội dung, ý tưởng chiến dịch, copywriting, thiết kế, video, TikTok/Reels."),("04","Mạng xã hội","Chiến lược kênh, nội dung, đăng tải, tương tác, cộng đồng, seeding, minigame."),("05","Website & nền tảng số","Cấu trúc, UI/UX, website, landing page, tích hợp CRM/chatbot/thanh toán, tracking, CRO."),("06","Truyền thông & Marketing hiệu suất","Media planning, quảng cáo số, OOH/DOOH, lead, chuyển đổi, retargeting, ROAS."),("07","SEO & tìm kiếm bằng AI","SEO kỹ thuật/on-page/off-page/nội dung, GEO, AEO, hiện diện trên AI Search."),("08","PR & người ảnh hưởng","PR, báo chí, KOL/KOC, livestream, seeding cộng đồng, sự kiện, activation."),("09","Dữ liệu & tăng trưởng","Tracking, dashboard, phễu, CRO, A/B testing, CRM, lead nurturing, giữ chân, social listening."),("10","Thương mại điện tử","Chiến lược kênh, quản trị gian hàng, quảng cáo sàn, affiliate, KOL/KOC bán hàng, livestream.")],""),"Marketing số",cls="port")
