A.page(svcpage("05 · Thiết kế & Sáng tạo","Thiết kế & Sáng tạo","Biến chiến lược, thông điệp và dữ liệu thành hệ thống nhận diện, hình ảnh và nội dung thị giác nhất quán — kết hợp định hướng nghệ thuật, sản xuất truyền thống và AI tạo sinh.","#F97316",[("01","Nhận diện thương hiệu & logo","Logo, hệ thống nhận diện, brand guideline, typography, màu sắc, icon, ứng dụng nhận diện, rebranding."),("02","Đồ họa & truyền thông thị giác","Key Visual, hình ảnh chiến dịch, thiết kế mạng xã hội, quảng cáo, thuyết trình, infographic, catalogue."),("03","Minh họa & nghệ thuật thị giác","Minh họa số, thiết kế nhân vật, họa tiết, storyboard, concept art, collage."),("04","Nhiếp ảnh & sản xuất video","Ảnh sản phẩm, thương hiệu, lifestyle, thời trang, F&B; phim thương hiệu, video quảng cáo, hậu kỳ."),("05","Sáng tạo & sản xuất bằng AI tạo sinh","Hình ảnh, video, avatar, giọng nói, âm nhạc bằng AI; tạo biến thể nội dung ở quy mô lớn.")],'<div class="card soft" style="margin-top:5mm"><div class="eyebrow" style="color:#F97316">Logic sản xuất sáng tạo</div><p style="margin-top:1mm"><b>Ý tưởng → Định hướng nghệ thuật → Sản xuất → Hậu kỳ → Chuyển thể → Mở rộng quy mô</b></p></div>'),"Thiết kế & Sáng tạo",cls="port")
A.page('''<div class="pad"><div class="eyebrow">06 · Hệ thống tăng trưởng tích hợp</div><h2 style="margin:2mm 0">Từ dịch vụ rời rạc đến một hệ thống</h2><p class="lead">Giá trị cốt lõi nằm ở khả năng kết nối các năng lực — thay vì tối ưu từng dịch vụ riêng lẻ.</p><div class="grid g2" style="margin-top:6mm">%s</div><div class="card soft" style="margin-top:5mm"><div class="eyebrow">Hành trình khách hàng</div><p style="margin-top:1mm"><b>Awareness → Consideration → Conversion → Retention → Growth</b></p><p class="small" style="margin-top:1mm">Dịch vụ được tổ chức theo từng giai đoạn và kết nối với đo lường, CRM, tự động hóa và AI để tạo vòng lặp tối ưu liên tục.</p></div></div>'''%"".join('<div class="card"><h3>%s</h3><p class="small">%s</p></div>'%x for x in (("Marketing","Xác định thị trường, khách hàng, hành trình, kênh và cơ chế tạo nhu cầu."),("Creative","Chuyển chiến lược thành thông điệp, hình ảnh và trải nghiệm tạo khác biệt."),("Data","Thiết lập đo lường, phân tích hành vi, phễu, hiệu quả kênh và cơ hội tối ưu."),("AI","Tăng tốc phân tích, tạo nội dung, truy xuất tri thức và hỗ trợ ra quyết định."),("Automation","Kết nối hệ thống và workflow để giảm thao tác lặp lại và mở rộng quy mô."),("Real Growth","Kết quả đo lường được, tối ưu liên tục, mở rộng khi đã chứng minh hiệu quả."))),"Hệ thống tích hợp",cls="port")
A.page('''<div class="pad"><div class="eyebrow">07 · Phương pháp triển khai</div><h2 style="margin:2mm 0">Audit. Build. Automate. Grow.</h2><div class="grid g2" style="margin-top:5mm">%s</div><h3 style="margin:6mm 0 3mm">Nguyên tắc triển khai</h3><div class="grid g2"><div class="card soft"><h3>Rõ mục tiêu</h3><p class="small">Xác định bài toán, phạm vi, KPI và cách đo trước khi mở rộng.</p></div><div class="card soft"><h3>Lặp có kiểm soát</h3><p class="small">Thử nghiệm nhanh, học từ dữ liệu, tối ưu theo chu kỳ.</p></div><div class="card soft"><h3>Con người kiểm soát</h3><p class="small">Giữ con người tại các điểm cần phán đoán hoặc trách nhiệm.</p></div><div class="card soft"><h3>Công nghệ phù hợp</h3><p class="small">Chọn công nghệ theo hệ thống và use case, tránh phụ thuộc một công cụ.</p></div></div><h3 style="margin:6mm 0 2mm">Hình thức hợp tác</h3><p class="small">Theo dự án · Hợp tác định kỳ (tháng/quý) · Tư vấn · Triển khai · Dịch vụ vận hành · Đào tạo · Đánh giá hiện trạng. Chi phí xác định theo phạm vi, độ phức tạp, hạng mục bàn giao, thời gian, công nghệ và yêu cầu vận hành.</p></div>'''%"".join('<div class="card" style="border-top:1.6mm solid %s"><div class="num" style="font-size:16pt;color:%s">%s</div><h3>%s</h3><p class="small">%s</p></div>'%x for x in (("#2563FF","#2563FF","01","Audit","Đánh giá hiện trạng: thị trường, khách hàng, thương hiệu, kênh, dữ liệu, quy trình, funnel, hệ thống công nghệ, mức độ sẵn sàng cho AI."),("#8B5CF6","#8B5CF6","02","Build","Xây nền tảng: chiến lược, thương hiệu, nội dung, website, cấu trúc chiến dịch, hệ thống đo lường, CRM, tài sản sáng tạo."),("#16A34A","#16A34A","03","Automate","Thiết kế workflow, AI Agent, chatbot; tự động hóa email, CRM, bán hàng, CSKH, báo cáo; tích hợp hệ thống qua API."),("#F97316","#F97316","04","Grow","Triển khai performance, SEO/AI Search, mạng xã hội, thương mại điện tử, CRO; đo lường và tối ưu theo dữ liệu."))),"Phương pháp",cls="port")
