# ======================================================= print templates from SVG (inline)
def svgtext(rel): return open(os.path.join(OUT,rel),encoding="utf8").read()
def printdoc(pages,size,title):
    html=html_doc(pages,css_extra="html,body{background:#fff}.p{page-break-after:always;break-after:page;overflow:hidden}.p svg{display:block;width:100%;height:100%}",pagesize=size)
    hp="/tmp/brandbuild/_pr_%s.html"%title; open(hp,"w",encoding="utf8").write(html); return hp
def pdf(hp,rel):
    out=os.path.join(OUT,rel); os.makedirs(os.path.dirname(out),exist_ok=True); return render.html_to_pdf(hp,out)
